CREATE TABLE epochs(id INTEGER PRIMARY KEY, started INTEGER NOT NULL, ended INTEGER);
CREATE TABLE settings(key TEXT PRIMARY KEY, value TEXT NOT NULL);
INSERT INTO settings VALUES('epoch','1');
INSERT INTO settings VALUES('frozen','0');
INSERT INTO epochs VALUES(1,unixepoch(),NULL);
CREATE TABLE players(id TEXT PRIMARY KEY, name TEXT NOT NULL, joined INTEGER NOT NULL);
CREATE TABLE accounts(player TEXT NOT NULL REFERENCES players(id), epoch INTEGER NOT NULL REFERENCES epochs(id), balance INTEGER NOT NULL DEFAULT 0 CHECK(balance>=0), rebirth INTEGER NOT NULL DEFAULT 0, PRIMARY KEY(player,epoch));
CREATE TABLE ledger(id TEXT PRIMARY KEY, epoch INTEGER NOT NULL, player TEXT NOT NULL, delta INTEGER NOT NULL, reason TEXT NOT NULL, created INTEGER NOT NULL);
CREATE INDEX ledger_player ON ledger(player,epoch,created);
CREATE TABLE runs(id TEXT PRIMARY KEY, player TEXT NOT NULL REFERENCES players(id), epoch INTEGER NOT NULL, seed INTEGER NOT NULL, profile TEXT NOT NULL, state TEXT NOT NULL, snapshot BLOB, created INTEGER NOT NULL, ended INTEGER, reward INTEGER NOT NULL DEFAULT 0, folder TEXT);
CREATE UNIQUE INDEX one_active_run ON runs(player) WHERE state IN ('PREPARING','ACTIVE','SETTLING');
CREATE TABLE contexts(player TEXT PRIMARY KEY REFERENCES players(id), hub BLOB, active TEXT);
CREATE TABLE unlocks(player TEXT NOT NULL, epoch INTEGER NOT NULL, id TEXT NOT NULL, PRIMARY KEY(player,epoch,id));
CREATE TABLE achievements(player TEXT NOT NULL, scope TEXT NOT NULL, id TEXT NOT NULL, earned INTEGER NOT NULL, PRIMARY KEY(player,scope,id));
CREATE TABLE trophies(player TEXT NOT NULL, id TEXT NOT NULL, earned INTEGER NOT NULL, PRIMARY KEY(player,id));
CREATE TABLE statistics(player TEXT NOT NULL, epoch INTEGER NOT NULL, metric TEXT NOT NULL, value INTEGER NOT NULL, day TEXT NOT NULL, PRIMARY KEY(player,epoch,metric,day));
CREATE TABLE assets(epoch INTEGER NOT NULL, id TEXT NOT NULL, price INTEGER NOT NULL CHECK(price>0), supply INTEGER NOT NULL CHECK(supply>=0), PRIMARY KEY(epoch,id));
CREATE TABLE holdings(player TEXT NOT NULL, epoch INTEGER NOT NULL, asset TEXT NOT NULL, quantity INTEGER NOT NULL CHECK(quantity>=0), PRIMARY KEY(player,epoch,asset));
CREATE TABLE market_history(id TEXT PRIMARY KEY, epoch INTEGER NOT NULL, asset TEXT NOT NULL, player TEXT NOT NULL, quantity INTEGER NOT NULL, price INTEGER NOT NULL, created INTEGER NOT NULL);
CREATE TABLE market_orders(id TEXT PRIMARY KEY, epoch INTEGER NOT NULL, player TEXT NOT NULL, asset TEXT NOT NULL, side TEXT NOT NULL, quantity INTEGER NOT NULL, limit_price INTEGER NOT NULL, state TEXT NOT NULL);
CREATE TABLE trades(id TEXT PRIMARY KEY, epoch INTEGER NOT NULL, a TEXT NOT NULL, b TEXT NOT NULL, state TEXT NOT NULL, offer_a BLOB, offer_b BLOB, coins_a INTEGER NOT NULL DEFAULT 0, coins_b INTEGER NOT NULL DEFAULT 0, accepted_a INTEGER NOT NULL DEFAULT 0, accepted_b INTEGER NOT NULL DEFAULT 0);
CREATE TABLE plots(id INTEGER PRIMARY KEY AUTOINCREMENT, player TEXT NOT NULL UNIQUE REFERENCES players(id), visitors INTEGER NOT NULL DEFAULT 1);
CREATE TABLE plot_trust(owner TEXT NOT NULL, visitor TEXT NOT NULL, PRIMARY KEY(owner,visitor));
CREATE TABLE npcs(id TEXT PRIMARY KEY, role TEXT NOT NULL, world TEXT NOT NULL, x REAL NOT NULL,y REAL NOT NULL,z REAL NOT NULL);
CREATE TABLE event_state(id TEXT PRIMARY KEY, enabled INTEGER NOT NULL);
CREATE TABLE resets(id TEXT PRIMARY KEY, old_epoch INTEGER NOT NULL, new_epoch INTEGER NOT NULL, stage TEXT NOT NULL, created INTEGER NOT NULL, backup TEXT);
CREATE TABLE leaderboard_history(epoch INTEGER NOT NULL, player TEXT NOT NULL, metric TEXT NOT NULL, value INTEGER NOT NULL, captured INTEGER NOT NULL, PRIMARY KEY(epoch,player,metric));
